	private static SailSource failAfterFlush(SailSource delegate, AtomicBoolean armed) {
		return new SailSource() {
			@Override
			public SailSource fork() {
				return delegate.fork();
			}

			@Override
			public SailSink sink(IsolationLevel level) {
				return delegate.sink(level);
			}

			@Override
			public SailDataset dataset(IsolationLevel level) {
				return delegate.dataset(level);
			}

			@Override
			public void prepare() {
				delegate.prepare();
			}

			@Override
			public void flush() {
				delegate.flush();
				if (armed.compareAndSet(true, false)) {
					throw new SailException("controlled initial import commit failure");
				}
			}

			@Override
			public void close() {
				delegate.close();
			}
		};
	}

